from typing import List

class Solution:
    def maxDistance(self, position: List[int], m: int) -> int:
        position.sort()
        lo, hi = 1, position[-1] - position[0]
        while lo <= hi:
            mid = lo + (hi - lo) // 2
            count = 1
            last = position[0]
            for x in position[1:]:
                if x - last >= mid:
                    count += 1
                    last = x
                    if count >= m:
                        break
            if count >= m:
                lo = mid + 1
            else:
                hi = mid - 1
        return hi

