        long lo = 1;
        long hi = position[position.length - 1] - position[0];
        while (lo <= hi) {
            long mid = lo + (hi - lo) / 2;
            int count = 1;
            long last = position[0];
            for (int i = 1; i < position.length; i++) {
                if (position[i] - last >= mid) {
                    count++;
                    last = position[i];
                    if (count >= m) break;
