class Solution {
public:
    long long maxDistance(vector<long long>& position, int m) {
        sort(position.begin(), position.end());
        long long lo = 1, hi = position.back() - position.front();
        while (lo <= hi) {
            long long mid = lo + (hi - lo) / 2;
            int count = 1;
            long long last = position.front();
            for (size_t i = 1; i < position.size(); ++i) {
                if (position[i] - last >= mid) {
                    ++count;
                    last = position[i];
                    if (count >= m) break;
                }
            }
            if (count >= m) lo = mid + 1;
            else hi = mid - 1;
        }
        return hi;
    }
};

vector<string> splitTop(const string& s) {
    vector<string> parts;
    int depth = 0, start = 0;
    for (int i = 0; i < (int)s.size(); ++i) {
        if (s[i] == '[') ++depth;
        else if (s[i] == ']') --depth;
        else if (s[i] == ',' && depth == 0) {
            parts.push_back(s.substr(start, i - start));
            start = i + 1;
        }
    }
    parts.push_back(s.substr(start));
    return parts;
}

vector<long long> parseLongVector(string s) {
    s.erase(remove_if(s.begin(), s.end(), ::isspace), s.end());
    if (s == "[]") return {};
    s = s.substr(1, s.size() - 2);
    vector<long long> a;
    for (const string& part : splitTop(s)) a.push_back(stoll(part));
    return a;
}

