#include <stdlib.h>
#include <string.h>
#include <ctype.h>

typedef struct {
    char *s;
    size_t pos;
    size_t len;
} Tok;

static void skip_separators(Tok *t) {
    while (t->pos < t->len && (t->s[t->pos] == ' ' || t->s[t->pos] == '\t' || t->s[t->pos] == '\r' || t->s[t->pos] == '\n' || t->s[t->pos] == ',')) t->pos++;
}

static char *next_token(Tok *t) {
    skip_separators(t);
    if (t->pos >= t->len) return NULL;
    size_t start = t->pos;
    if (t->s[t->pos] == '[') {
        int depth = 0;
        while (t->pos < t->len) {
            char c = t->s[t->pos++];
            if (c == '[') depth++;
            else if (c == ']') {
                depth--;
                if (depth == 0) break;
            }
        }
    } else {
        while (t->pos < t->len && t->s[t->pos] != ',' && t->s[t->pos] != ']') t->pos++;
    }
    size_t n = t->pos - start;
    char *out = (char *)malloc(n + 1);
    if (!out) return NULL;
    memcpy(out, t->s + start, n);
    out[n] = '\0';
    return out;
}

static long long *parse_ll_array(Tok *t, int *out_n) {
    char *tok = next_token(t);
    if (!tok) { *out_n = 0; return NULL; }
    size_t len = strlen(tok);
    if (len == 2 && tok[0] == '[' && tok[1] == ']') {
        free(tok); *out_n = 0; return NULL;
    }
    char *inner = (char *)malloc(len - 1);
    memcpy(inner, tok + 1, len - 2);
    inner[len - 2] = '\0';
    free(tok);
    int n = 1;
    for (size_t i = 0; inner[i]; ++i) if (inner[i] == ',') n++;
    long long *a = (long long *)malloc((size_t)n * sizeof(long long));
    if (!a) { free(inner); *out_n = 0; return NULL; }
    char *p = inner;
    for (int i = 0; i < n; ++i) {
        char *end = NULL;
        a[i] = strtoll(p, &end, 10);
        p = (*end == ',') ? end + 1 : end;
    }
    free(inner);
    *out_n = n;
    return a;
}

static int cmp_ll(const void *a, const void *b) {
    long long x = *(const long long *)a, y = *(const long long *)b;
    return (x > y) - (x < y);
}

long long maxDistance(long long *position, int positionSize, int m) {
    qsort(position, (size_t)positionSize, sizeof(long long), cmp_ll);
    long long lo = 1, hi = position[positionSize - 1] - position[0];
    while (lo <= hi) {
        long long mid = lo + (hi - lo) / 2;
        int count = 1;
        long long last = position[0];
        for (int i = 1; i < positionSize; ++i) {
            if (position[i] - last >= mid) {
                count++;
                last = position[i];
                if (count >= m) break;
            }
        }
        if (count >= m) lo = mid + 1;
        else hi = mid - 1;
    }
    return hi;
}

